CREATE TABLE users (id TEXT PRIMARY KEY, identity TEXT NOT NULL CHECK(json_valid(identity)), revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE settings (id TEXT PRIMARY KEY CHECK(id='main'), payload TEXT NOT NULL CHECK(json_valid(payload)), revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE actor_bindings (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), instance_id TEXT NOT NULL, actor_key TEXT NOT NULL, session_key TEXT NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), revision INTEGER NOT NULL DEFAULT 0, UNIQUE(instance_id,actor_key,session_key));
CREATE TABLE account_scopes (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), region TEXT NOT NULL CHECK(region='cn'), fingerprint TEXT, credential_generation INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('active','paused','retired')), created_at REAL NOT NULL);
CREATE UNIQUE INDEX one_active_account ON account_scopes(state) WHERE state='active';
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), question TEXT CHECK(question IS NULL OR json_valid(question)), question_expires REAL, query TEXT CHECK(query IS NULL OR json_valid(query)), query_revision INTEGER NOT NULL DEFAULT 0, recent TEXT CHECK(recent IS NULL OR json_valid(recent)), revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE material_groups (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES sessions(id), mode TEXT NOT NULL CHECK(mode IN ('automatic','explicit','direct')), state TEXT NOT NULL CHECK(state IN ('collecting','awaiting_materials','awaiting_clarification','task_saved_attachments_pending','partially_done','completed','cancelled')), first_at REAL NOT NULL, last_at REAL NOT NULL, closes_at REAL NOT NULL, revision INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX one_collecting_group ON material_groups(session_id) WHERE state='collecting';
CREATE TABLE message_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), group_id TEXT REFERENCES material_groups(id), instance_id TEXT NOT NULL, session_key TEXT NOT NULL, message_key TEXT NOT NULL, received_at REAL NOT NULL, envelope TEXT NOT NULL CHECK(json_valid(envelope)), state TEXT NOT NULL CHECK(state IN ('admitted','pending','processed','rejected')), UNIQUE(instance_id,session_key,message_key));
CREATE TABLE blobs (hash TEXT PRIMARY KEY CHECK(length(hash)=64), size INTEGER NOT NULL CHECK(size>=0), path TEXT NOT NULL UNIQUE, created_at REAL NOT NULL);
CREATE TABLE assets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), group_id TEXT NOT NULL REFERENCES material_groups(id), message_id TEXT REFERENCES message_records(id), hash TEXT REFERENCES blobs(hash), name TEXT NOT NULL, source_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','ready','unavailable')), error TEXT, created_at REAL NOT NULL, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE media_acquisitions (id TEXT PRIMARY KEY, asset_id TEXT NOT NULL UNIQUE REFERENCES assets(id), state TEXT NOT NULL CHECK(state IN ('pending','running','done','unavailable')), recoverable_ref TEXT, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE material_segments (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES material_groups(id), source_id TEXT NOT NULL, location TEXT NOT NULL, text TEXT NOT NULL, normalized_text TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('read','unknown')), reason TEXT, UNIQUE(group_id,source_id,location));
CREATE TABLE evidence_records (id TEXT PRIMARY KEY, segment_id TEXT NOT NULL REFERENCES material_segments(id), quote TEXT NOT NULL, verified INTEGER NOT NULL CHECK(verified IN (0,1)));
CREATE TABLE notice_records (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES material_groups(id), user_id TEXT NOT NULL REFERENCES users(id), state TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, created_at REAL NOT NULL);
CREATE TABLE notice_versions (id TEXT PRIMARY KEY, notice_id TEXT NOT NULL REFERENCES notice_records(id), revision INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), fingerprint TEXT NOT NULL, created_at REAL NOT NULL, UNIQUE(notice_id,revision));
CREATE TABLE action_items (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), notice_id TEXT REFERENCES notice_records(id), identity_key TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE action_item_versions (id TEXT PRIMARY KEY, action_id TEXT NOT NULL REFERENCES action_items(id), revision INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at REAL NOT NULL, UNIQUE(action_id,revision));
CREATE TABLE operations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), account_ref TEXT NOT NULL REFERENCES account_scopes(id), action_id TEXT REFERENCES action_items(id), kind TEXT NOT NULL CHECK(kind IN ('create','update','complete','upload')), operation_key TEXT NOT NULL UNIQUE, plan TEXT NOT NULL CHECK(json_valid(plan)), state TEXT NOT NULL CHECK(state IN ('validated','executing','succeeded','failed_safe','outcome_unknown','created_unverified','uploaded_unverified','applied_unverified','cancelled')), paused INTEGER NOT NULL DEFAULT 0 CHECK(paused IN (0,1)), remote_id TEXT, result TEXT CHECK(result IS NULL OR json_valid(result)), attempt INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, created_at REAL NOT NULL, checked_at REAL);
CREATE INDEX operation_state ON operations(state,paused,created_at);
CREATE TABLE notice_task_links (id TEXT PRIMARY KEY, notice_id TEXT REFERENCES notice_records(id), action_id TEXT NOT NULL REFERENCES action_items(id), account_ref TEXT NOT NULL REFERENCES account_scopes(id), project_id TEXT NOT NULL, task_id TEXT NOT NULL, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), UNIQUE(action_id,account_ref,project_id,task_id));
CREATE TABLE task_attachment_links (id TEXT PRIMARY KEY, account_ref TEXT NOT NULL REFERENCES account_scopes(id), project_id TEXT NOT NULL, task_id TEXT NOT NULL, hash TEXT NOT NULL REFERENCES blobs(hash), asset_id TEXT NOT NULL REFERENCES assets(id), remote_id TEXT, operation_id TEXT NOT NULL REFERENCES operations(id), verified INTEGER NOT NULL DEFAULT 0 CHECK(verified IN (0,1)), UNIQUE(account_ref,project_id,task_id,hash));
CREATE TABLE jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('acquire_material','read_materials','close_group','parse_group','execute_operation','reconcile','send_receipt')), dedupe_key TEXT NOT NULL UNIQUE, payload TEXT NOT NULL CHECK(json_valid(payload)), state TEXT NOT NULL CHECK(state IN ('pending','running','done','failed')), priority INTEGER NOT NULL DEFAULT 10, available_at REAL NOT NULL, owner TEXT, attempt INTEGER NOT NULL DEFAULT 0, error TEXT, created_at REAL NOT NULL);
CREATE INDEX jobs_ready ON jobs(state,available_at,priority,created_at);
CREATE TABLE receipt_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), operation_id TEXT REFERENCES operations(id), dedupe_key TEXT NOT NULL UNIQUE, origin TEXT NOT NULL, body TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','sent','failed','unknown')), attempt INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, created_at REAL NOT NULL);
CREATE TABLE api_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), endpoint TEXT NOT NULL, target TEXT NOT NULL, request_id TEXT NOT NULL, fingerprint TEXT NOT NULL, response TEXT NOT NULL CHECK(json_valid(response)), created_at REAL NOT NULL, UNIQUE(user_id,endpoint,target,request_id));
CREATE TABLE source_registry (id TEXT PRIMARY KEY, state TEXT NOT NULL CHECK(state IN ('planned','disabled')), payload TEXT NOT NULL CHECK(json_valid(payload)));
